css:
.fx-snp{width:min(1000px,100%);position:relative}
.fx-snp .hint{opacity:.5;font-size:.85em;text-align:center;padding:1em 0}
.fx-snp .wrap{position:relative}
.fx-snp .vp{height:min(72vh,600px);overflow-y:auto;scroll-snap-type:y mandatory;scroll-behavior:smooth;border-radius:var(--radius);border:1px solid var(--border);outline-offset:3px}
.fx-snp .pn{height:100%;scroll-snap-align:start;scroll-snap-stop:always;display:grid;align-content:center;gap:.5em;padding:2em 4.5em 2em 2.5em;color:var(--on-primary);background:var(--primary)}
.fx-snp .pn:nth-child(2){background:var(--accent);color:var(--on-accent)}
.fx-snp .pn:nth-child(3){background:var(--secondary)}
.fx-snp .pn:nth-child(4){background:color-mix(in srgb,var(--primary) 60%,#000)}
.fx-snp .n{font:700 clamp(4em,12vw,8em)/1 var(--font-heading);opacity:.28}
.fx-snp h3{font-size:clamp(1.6em,4vw,2.6em)}.fx-snp .pn p{opacity:.9;max-width:36ch}
.fx-snp .dots{position:absolute;right:1.1em;top:50%;transform:translateY(-50%);display:grid;gap:.7em}
.fx-snp .dots button{width:.8em;height:.8em;padding:0;border-radius:50%;border:2px solid #fff;background:transparent;cursor:pointer;transition:background calc(.2s/var(--speed)),transform calc(.2s/var(--speed))}
.fx-snp .dots button[aria-current=true]{background:#fff;transform:scale(1.25)}
.fx-snp .dots button:focus-visible{outline:2px solid #fff;outline-offset:3px}
@media(prefers-reduced-motion:reduce){.fx-snp .vp{scroll-behavior:auto}}

js:
(function(){var root=document.querySelector('.fx-snp'),vp=root.querySelector('.vp'),ps=vp.querySelectorAll('.pn'),nav=root.querySelector('.dots');
ps.forEach(function(p,i){var b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Go to panel '+(i+1));b.onclick=function(){vp.scrollTo({top:p.offsetTop})};nav.appendChild(b)});
var bs=nav.querySelectorAll('button');
function mark(){var i=Math.round(vp.scrollTop/vp.clientHeight);bs.forEach(function(b,j){b.setAttribute('aria-current',j===i)})}
vp.addEventListener('scroll',mark,{passive:true});mark()})();
